<?php use App\Core\View;ob_start(); ?><h1>Painel</h1><?php if(!$subscribed): ?><p class="warning">Você ainda não possui uma assinatura ativa. <a href="/planos">Escolher plano</a></p><?php endif ?><div class="grid"><article><b><?=View::e((string)$stats['total'])?></b><br>Contatos</article><article><b><?=View::e((string)$stats['active'])?></b><br>Ativos</article></div><h2>Campanhas</h2><a class="btn" href="/campanhas/nova">Nova campanha</a><table><tr><th>Título</th><th>Status</th><th>Enviados</th><th>Ação</th></tr><?php foreach($campaigns as $c): ?><tr data-campaign="<?=$c['id']?>"><td><?=View::e($c['title'])?></td><td class="status"><?=View::e($c['status'])?></td><td class="progress"><?=View::e((string)$c['sent'])?> / <?=View::e((string)$c['recipients'])?></td><td><?php if($c['status']==='draft'): ?><form method="post" action="/campanhas/finalizar"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button>Finalizar</button></form><?php elseif(in_array($c['status'],['queued','running','paused'])): ?><form method="post" action="/campanhas/status"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="id" value="<?=$c['id']?>"><input type="hidden" name="status" value="<?=$c['status']==='paused'?'queued':'paused'?>"><button><?=$c['status']==='paused'?'Retomar':'Pausar'?></button></form><?php endif ?></td></tr><?php endforeach ?></table><script>setInterval(()=>document.querySelectorAll('[data-campaign]').forEach(async r=>{let d=await fetch('/campanhas/status?id='+r.dataset.campaign).then(x=>x.json());r.querySelector('.status').textContent=d.status;r.querySelector('.progress').textContent=`${d.sent||0} / ${d.total||0} · ${d.eta_minutes||0} min`}),10000)</script><?php $body=ob_get_clean();$title='Painel';require __DIR__.'/layout.php'; ?>
